// U-1 (item 159): THE one Chatwoot client of the Studio. Every page and store that talks to Chatwoot goes through it,
// and it goes only to the Studio's own gateway (/api/cw/..., src/app/api/cw/[...path]/route.ts), never to Chatwoot:
// the token, the account id and the address lock stay on the server.
//
// Built with the standard tools, not by hand (task U-1 §1, "no manual build from scratch"):
// - Types: generated by openapi-typescript 7.13.0 from Chatwoot v4.18.0's own OpenAPI file (swagger/swagger.json of
//   tag v4.18.0, sha256 775d8352…6ef8) into ./cw-openapi.d.ts. To regenerate:
//     npx openapi-typescript <chatwoot v4.18.0>/swagger/swagger.json -o src/lib/chatwoot/cw-openapi.d.ts
//     npx biome format --write src/lib/chatwoot/cw-openapi.d.ts
//   (the file the task named, claude-2/chatwoot-settings-inventory/src/cw-v4.18.0/swagger/swagger.json, does not exist
//   in that folder; the same file of tag v4.18.0 was used: codex-3/conversation-status/sources/chatwoot-v4.18.0/swagger/
//   swagger.json, identical to raw.githubusercontent.com/chatwoot/chatwoot/v4.18.0/swagger/swagger.json.)
// - Calls: openapi-fetch 0.17.0 (createClient), typed by those paths.
// Below, the generated paths are re-keyed to the gateway's (the "/api/v1/accounts/{account_id}" prefix and the
// account_id parameter dropped: the server adds them), cut down to the gateway's allow list and its methods
// (./gateway-policy.ts ROUTES), and completed with the paths config/routes.rb of v4.18.0 has but swagger.json does not
// (RoutesRbPaths). The ten areas absent from CE are answered by the gateway with 501 (ceUnavailable below says the same
// without a call).
import createClient, { type ClientOptions } from "openapi-fetch";

import type { paths as ChatwootSpecPaths } from "./cw-openapi";
import { type CeUnavailableArea, type CeUnavailableBody, ceUnavailableBody } from "./gateway-policy";

export {
  CE_UNAVAILABLE,
  type CeUnavailableArea,
  type CeUnavailableBody,
  SECRET_KEYS,
  scrubSecrets,
} from "./gateway-policy";

/* ------------------------------------------------------------------ generated paths -> gateway paths ------------ */

type Method = "get" | "put" | "post" | "delete" | "options" | "head" | "patch" | "trace";

/** `parameters` without account_id in `path` (and `path?: never` when nothing is left). */
type DropAccountParam<P> = P extends { path: infer Q }
  ? Omit<P, "path"> &
      (Exclude<keyof Q, "account_id"> extends never ? { path?: never } : { path: Omit<Q, "account_id"> })
  : P;

type DropAccountOp<T> = T extends { parameters: infer P }
  ? Omit<T, "parameters"> & { parameters: DropAccountParam<P> }
  : T;

type DropAccountItem<I> = {
  [K in keyof I]: K extends "parameters" ? DropAccountParam<I[K]> : K extends Method ? DropAccountOp<I[K]> : I[K];
};

type GatewayKey<K> = K extends `/api/v1/accounts/{account_id}${infer R}`
  ? R extends ""
    ? never
    : R
  : K extends `/api/v2/accounts/{account_id}${infer R}`
    ? R extends ""
      ? never
      : R
    : K extends "/api/v1/profile"
      ? "/profile"
      : never;

/** Every generated account path under its gateway name ("/conversations/{conversation_id}/messages", ...). */
export type SpecUnderGateway = {
  [K in keyof ChatwootSpecPaths as GatewayKey<K>]: DropAccountItem<ChatwootSpecPaths[K]>;
};

/** A path item cut down to the methods the gateway allows on it (the others become `?: never`, so not callable). */
type Only<I, M extends Method> = Pick<I, Extract<keyof I, M | "parameters">> & { [K in Exclude<Method, M>]?: never };

type S = SpecUnderGateway;

/** The generated paths the gateway allows (task U-1 §1-b, §1-c, and U-3), with their allowed methods only. */
export type SpecAllowedPaths = {
  "/profile": Only<S["/profile"], "get">;
  "/conversations": Only<S["/conversations"], "get">;
  "/conversations/meta": Only<S["/conversations/meta"], "get">;
  "/conversations/{conversation_id}": Only<S["/conversations/{conversation_id}"], "get">;
  "/conversations/{conversation_id}/messages": Only<S["/conversations/{conversation_id}/messages"], "get" | "post">;
  "/conversations/{conversation_id}/labels": Only<S["/conversations/{conversation_id}/labels"], "get" | "post">;
  "/conversations/{conversation_id}/toggle_status": Only<S["/conversations/{conversation_id}/toggle_status"], "post">;
  "/conversations/{conversation_id}/toggle_priority": Only<
    S["/conversations/{conversation_id}/toggle_priority"],
    "post"
  >;
  "/conversations/{conversation_id}/assignments": Only<S["/conversations/{conversation_id}/assignments"], "post">;
  "/contacts": Only<S["/contacts"], "get" | "post">;
  "/contacts/search": Only<S["/contacts/search"], "get">;
  "/contacts/{id}": Only<S["/contacts/{id}"], "get" | "put" | "delete">;
  "/contacts/{id}/conversations": Only<S["/contacts/{id}/conversations"], "get">;
  "/inboxes": Only<S["/inboxes"], "get">;
  "/inboxes/{id}": Only<S["/inboxes/{id}"], "get" | "patch">;
  "/inbox_members/{inbox_id}": Only<S["/inbox_members/{inbox_id}"], "get" | "post">;
  "/inbox_members": Only<S["/inbox_members"], "post" | "patch" | "delete">;
  "/agents": Only<S["/agents"], "get">;
  "/teams": Only<S["/teams"], "get" | "post">;
  "/teams/{team_id}": Only<S["/teams/{team_id}"], "get" | "patch" | "delete">;
  "/teams/{team_id}/team_members": Only<S["/teams/{team_id}/team_members"], "get" | "post" | "patch" | "delete">;
  "/labels": Only<S["/labels"], "get" | "post">;
  "/labels/{id}": Only<S["/labels/{id}"], "get" | "patch" | "delete">;
  "/canned_responses": Only<S["/canned_responses"], "get" | "post">;
  "/canned_responses/{id}": Only<S["/canned_responses/{id}"], "get" | "patch" | "delete">;
  "/custom_filters": Only<S["/custom_filters"], "get" | "post">;
  "/custom_filters/{custom_filter_id}": Only<S["/custom_filters/{custom_filter_id}"], "get" | "patch" | "delete">;
  "/custom_attribute_definitions": Only<S["/custom_attribute_definitions"], "get" | "post">;
  "/custom_attribute_definitions/{id}": Only<S["/custom_attribute_definitions/{id}"], "get" | "patch" | "delete">;
  "/automation_rules": Only<S["/automation_rules"], "get" | "post">;
  "/automation_rules/{id}": Only<S["/automation_rules/{id}"], "get" | "patch" | "delete">;
  "/webhooks": Only<S["/webhooks"], "get">;
  "/reports": Only<S["/reports"], "get">;
  "/reports/summary": Only<S["/reports/summary"], "get">;
  "/reports/conversations": Only<S["/reports/conversations"], "get">;
  "/reports/first_response_time_distribution": Only<S["/reports/first_response_time_distribution"], "get">;
  "/reports/inbox_label_matrix": Only<S["/reports/inbox_label_matrix"], "get">;
  "/reports/outgoing_messages_count": Only<S["/reports/outgoing_messages_count"], "get">;
  "/summary_reports/agent": Only<S["/summary_reports/agent"], "get">;
  "/summary_reports/inbox": Only<S["/summary_reports/inbox"], "get">;
  "/summary_reports/team": Only<S["/summary_reports/team"], "get">;
  "/summary_reports/channel": Only<S["/summary_reports/channel"], "get">;
};

/* ------------------------------------------------------------------ config/routes.rb paths not in swagger.json -- */
// Chatwoot v4.18.0 config/routes.rb has these, swagger.json does not describe them, so their answers are typed as
// JSON without a schema (`unknown`): the caller narrows it. Line numbers are routes.rb's.

type JsonAnswer = { headers: { [name: string]: unknown }; content: { "application/json": unknown } };
type RbQuery = Record<string, string | number | boolean | undefined>;
type RbBody = { content: { "application/json": Record<string, unknown> } };
interface RbGet<PathParams> {
  parameters: {
    query?: RbQuery;
    header?: never;
    path: PathParams;
    cookie?: never;
  };
  requestBody?: never;
  responses: { 200: JsonAnswer; 403: JsonAnswer; 404: JsonAnswer };
}
interface RbGetNoPath {
  parameters: { query?: RbQuery; header?: never; path?: never; cookie?: never };
  requestBody?: never;
  responses: { 200: JsonAnswer; 403: JsonAnswer; 404: JsonAnswer };
}
interface RbWrite<PathParams> {
  parameters: {
    query?: RbQuery;
    header?: never;
    path: PathParams;
    cookie?: never;
  };
  requestBody?: RbBody;
  responses: { 200: JsonAnswer; 204: JsonAnswer; 403: JsonAnswer; 404: JsonAnswer; 422: JsonAnswer };
}
interface RbWriteNoPath {
  parameters: { query?: RbQuery; header?: never; path?: never; cookie?: never };
  requestBody?: RbBody;
  responses: { 200: JsonAnswer; 204: JsonAnswer; 403: JsonAnswer; 404: JsonAnswer; 422: JsonAnswer };
}
type RbItem<Get> = { parameters: { query?: never; header?: never; path?: never; cookie?: never }; get: Get } & {
  [K in Exclude<Method, "get">]?: never;
};
type RbCrudNoPath = {
  parameters: { query?: never; header?: never; path?: never; cookie?: never };
  get: RbGetNoPath;
  post: RbWriteNoPath;
} & { [K in Exclude<Method, "get" | "post">]?: never };
type RbCrudId = {
  parameters: { query?: never; header?: never; path?: never; cookie?: never };
  get: RbGet<Id>;
  put: RbWrite<Id>;
  patch: RbWrite<Id>;
  delete: RbWrite<Id>;
} & { [K in Exclude<Method, "get" | "put" | "patch" | "delete">]?: never };
type RbPostId = {
  parameters: { query?: never; header?: never; path?: never; cookie?: never };
  post: RbWrite<Id>;
} & { [K in Exclude<Method, "post">]?: never };
type RbPostNoPath = {
  parameters: { query?: never; header?: never; path?: never; cookie?: never };
  post: RbWriteNoPath;
} & { [K in Exclude<Method, "post">]?: never };
type RbPatchPutId = {
  parameters: { query?: never; header?: never; path?: never; cookie?: never };
  put: RbWrite<Id>;
  patch: RbWrite<Id>;
} & { [K in Exclude<Method, "put" | "patch">]?: never };
type Conv = { conversation_id: number };
type Id = { id: number };

export type RoutesRbPaths = {
  /** routes.rb:116 resources :accounts (show only; writes are forbidden by gateway-policy) */
  "/accounts/{id}": RbItem<RbGet<Id>>;
  /** routes.rb:193 get :attachments (conversations member) */
  "/conversations/{conversation_id}/attachments": RbItem<RbGet<Conv>>;
  /** routes.rb:178 resource :participants (show) */
  "/conversations/{conversation_id}/participants": RbItem<RbGet<Conv>>;
  /**
   * In the task's allow list; routes.rb:241 opens contact_inboxes for create only, so Chatwoot answers 404 to GET
   * (the gateway passes that 404 on, it does not invent a list).
   */
  "/contacts/{id}/contact_inboxes": RbItem<RbGet<Id>>;
  /** routes.rb:199-206 resources :search (index, conversations, messages, contacts) */
  "/search": RbItem<RbGetNoPath>;
  "/search/conversations": RbItem<RbGetNoPath>;
  "/search/messages": RbItem<RbGetNoPath>;
  "/search/contacts": RbItem<RbGetNoPath>;
  /** routes.rb:140 resources :macros (index, show, create, update, destroy, execute) */
  "/macros": RbCrudNoPath;
  "/macros/{id}": RbCrudId;
  "/macros/{id}/execute": RbPostId;
  /** routes.rb:135 automation_rules member post :clone */
  "/automation_rules/{id}/clone": RbPostId;
  /** routes.rb:331 resources :notifications (index) */
  "/notifications": RbItem<RbGetNoPath>;
  /** routes.rb:333 collection post :read_all */
  "/notifications/read_all": RbPostNoPath;
  /** routes.rb:331 member update (mark read) */
  "/notifications/{id}": RbPatchPutId;
  /** routes.rb:561-563 (api/v2) live_reports & summary_reports & bot reports */
  "/live_reports/conversation_metrics": RbItem<RbGetNoPath>;
  "/live_reports/grouped_conversation_metrics": RbItem<RbGetNoPath>;
  "/summary_reports/label": RbItem<RbGetNoPath>;
  "/reports/bot_summary": RbItem<RbGetNoPath>;
  "/reports/bot_metrics": RbItem<RbGetNoPath>;
  /** routes.rb:260 resources :csat_survey_responses (index, metrics) */
  "/csat_survey_responses": RbItem<RbGetNoPath>;
  "/csat_survey_responses/metrics": RbItem<RbGetNoPath>;
  /** V-15: routes.rb resources :portals, :portals do resources :articles, :categories (read-only GET) */
  "/portals": RbItem<RbGetNoPath>;
  "/portals/{id}": RbItem<RbGet<Id>>;
  "/portals/{portal_id}/articles": RbItem<RbGet<{ portal_id: number }>>;
  "/portals/{portal_id}/categories": RbItem<RbGet<{ portal_id: number }>>;
  /** V-15: routes.rb resources :campaigns (read-only GET) */
  "/campaigns": RbItem<RbGetNoPath>;
  "/campaigns/{id}": RbItem<RbGet<Id>>;
};

/** Every path the gateway answers, typed: the generated ones it allows plus the routes.rb ones. */
export type GatewayPaths = SpecAllowedPaths & RoutesRbPaths;

/* ------------------------------------------------------------------ the client ---------------------------------- */

/**
 * A client of the gateway. In the browser the defaults are right (same origin, "/api/cw", the View as cookie goes with
 * the request). The contract tests pass an absolute baseUrl and a Cookie header.
 */
export function createUnifiedClient(options: ClientOptions = {}) {
  return createClient<GatewayPaths>({ baseUrl: "/api/cw", credentials: "same-origin", ...options });
}

export type UnifiedClient = ReturnType<typeof createUnifiedClient>;

/** The Studio's one client (browser). */
export const cw: UnifiedClient = createUnifiedClient();

/** For FormData bodies (a reply with files, Chatwoot's `attachments[]`): send the FormData as it is. */
export const formDataBody = { bodySerializer: (body: unknown) => body as FormData } as const;

/** The honest "not in this edition" answer for one of the ten CE-absent areas, without a call. */
export function ceUnavailable(area: CeUnavailableArea): CeUnavailableBody {
  return ceUnavailableBody(area);
}

/** True when a gateway answer is the CE-absent one (status 501 with available: false). */
export function isCeUnavailable(status: number, body: unknown): body is CeUnavailableBody {
  return (
    status === 501 &&
    Boolean(body) &&
    typeof body === "object" &&
    (body as { available?: unknown }).available === false &&
    (body as { edition?: unknown }).edition === "ce"
  );
}
